other.dispose();
const first = dsl.execute({ commandId: 'same', type: 'selection.set', payload: { entityIds: [id] } });
const again = dsl.execute({ commandId: 'same', type: 'selection.set', payload: { entityIds: [id] } });
log('幂等（同一 Promise）', first === again);
const conflict = await dsl.execute({ commandId: 'same', type: 'selection.set', payload: { entityIds: [] } });
const stale = await dsl.execute({ commandId: 'stale', sceneInstanceId: 'scene-run-old', type: 'camera.reset', payload: {} });
const missing = await dsl.execute({ commandId: 'missing', type: 'camera.focus', payload: { entityId: 'NO-SUCH-ENTITY' } });
