`)},{id:"heatmap.mapping",title:"分段颜色映射",api:"heatMapStyle.colorMapping",description:"按 valueArray / colorArray 分段着色。",code:Ce(`
const features = [];
for (let x = -6; x <= 6; x += 1.5) for (let z = -5; z <= 5; z += 1.5) features.push({ point: [x, 0, z], value: 50 + 50 * Math.sin(x / 3) * Math.cos(z / 3) });
await viewer.scene.add(new sdk.HeatMap({ points: { features }, heatMapStyle: { brushDiameter: 3, blendMode: 'max', colorMapping: { valueArray: [20, 50, 80], colorArray: ['00ffff', 'ffff00', 'ff0000'] } } }));
await viewer.camera.flyTo({ id: 'h', name: 'h', position: [0, 16, 12], target: [0, 0, 0] }, 600);
`)},{id:"heatmap.update",title:"实时更新热力点",api:"heatmap.update({ points })",description:"每秒刷新一次热力数据。",code:Ce(`
const make = () => Array.from({ length: 120 }, () => ({ point: [(Math.random() - 0.5) * 14, 0, (Math.random() - 0.5) * 10], value: Math.random() * 100 }));
const [heat] = await viewer.scene.add(new sdk.HeatMap({ points: { features: make() } }));
setInterval(() => { heat.update({ points: { features: make() } }).catch(e => log.error(e)); }, 1000);
log('热力数据每秒刷新，运行其他示例时停止');
`)},{id:"heatmap.delete",title:"删除热力图",api:"heatmap.delete",description:"添加后删除。",code:Ce(`
